          <div className="bg-white dark:bg-slate-900 w-full max-w-7xl h-[95vh] rounded-3xl shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95 duration-300">
            {/* Modal Header */}
            <div className="p-6 border-b border-gray-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900 z-10 shadow-sm">
              <div>
                <h2 className="text-2xl font-bold text-purple-600 dark:text-purple-400">ពិនិត្យមើលស្លាយពិត</h2>
