      if (!relevantData.subject || !relevantData.lessonTitle || !relevantData.classInCharge) {
        setError("សូមបំពេញ មុខវិជ្ជា, ចំណងជើងមេរៀន, និង ថ្នាក់ទទួលបន្ទុក ដើម្បីបង្កើតមាតិកាដោយ AI។");
        setIsLoadingAI(false);
        return;
