export const generateImageForSlide = async (prompt: string, isLowerGrade: boolean): Promise<string> => {
    if (!process.env.API_KEY || !prompt) return ""; 
    try {
        const style = isLowerGrade 
            ? "vibrant 3D cartoon style, Pixar-like, friendly, bright colors, white background, high detail, educational for children"
            : "clean educational vector art, flat design, professional, informative";

        const response: GenerateContentResponse = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: `${prompt}, ${style}` }] },
            config: { imageConfig: { aspectRatio: "16:9" } },
        }));

        const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
        return part ? `data:${part.inlineData.mimeType};base64,${part.inlineData.data}` : "";
    } catch { return ""; }
}

export const createPptxPresentation = async (presentationTitle: string, slides: SlideContent[], formData: LessonPlanFormState): Promise<Blob> => {
    const pptx = new PptxGenJS();
    pptx.layout = 'LAYOUT_16x9'; 
    const KHMER_FONT = "Khmer OS Siemreap";
    const COLOR_MAIN = "0B2D5D";
    const isLowerGrade = /1|2|3|១|២|៣/.test(formData.classInCharge || "");

    pptx.defineSlideMaster({
        title: "KIDS_MASTER",
        background: { color: "FFFFFF" },
        objects: [
            { rect: { x: 0, y: '95%', w: '100%', h: '5%', fill: { color: COLOR_MAIN } } },
            { text: { text: formData.lessonTitle, options: { x: 0.2, y: '95.5%', w: '60%', fontFace: KHMER_FONT, fontSize: 10, color: "FFFFFF" } } }
        ],
    });

    let titleSlide = pptx.addSlide({ masterName: "KIDS_MASTER" });
    titleSlide.addShape(pptx.ShapeType.roundRect, { x: 0.5, y: 0.5, w: '94%', h: '88%', fill: { color: isLowerGrade ? 'FFF9E3' : 'F0F8FF' }, line: { color: 'FF9900', width: 2 } });
    titleSlide.addText(presentationTitle, {
        x: 0.5, y: 2.5, w: '90%', align: 'center', fontFace: KHMER_FONT, fontSize: 44, bold: true, color: COLOR_MAIN,
        animate: { type: 'fade', delay: 200 }
    });

    slides.forEach((s) => {
        let slide = pptx.addSlide({ masterName: "KIDS_MASTER" });
        slide.addText(s.slideTitle, { 
            x: 0.5, y: 0.3, w: '90%', fontFace: KHMER_FONT, fontSize: 32, bold: true, color: COLOR_MAIN,
            animate: { type: 'flyIn', direction: 'l', duration: 1 }
        });

        if (s.imageData) {
            slide.addImage({ data: s.imageData, x: 0.5, y: 1.5, w: 4.8, h: 4.2, sizing: { type: 'contain', w: 4.8, h: 4.2 } });
            slide.addText(s.slideContent, {
                x: 5.5, y: 1.5, w: 4.0, fontFace: KHMER_FONT, fontSize: 24, color: "333333",
                bullet: true, valign: 'top', animate: { type: 'fade', delay: 500 }
            });
        } else {
            slide.addText(s.slideContent, { 
                x: 0.5, y: 1.5, w: '90%', fontFace: KHMER_FONT, fontSize: 28, color: "333333",
                bullet: true, valign: 'top', animate: { type: 'fade', delay: 500 }
            });
        }
    });

    return pptx.write({ outputType: 'blob' }) as Promise<Blob>; 
};

export const prepareSlideContent = async (formData: LessonPlanFormState): Promise<SlideContent[]> => {
    const lessonContent = formData.activities.map(act => act.lessonContent).filter(Boolean).join('\n\n');
    const isLowerGrade = /1|2|3|១|២|៣/.test(formData.classInCharge || "");
    const structures = await generateSlideStructures(lessonContent, formData.lessonTitle, formData.subject, formData.classInCharge);

    const slidesWithImages: SlideContent[] = [];
    for (const struct of structures) {
        const img = await generateImageForSlide(struct.imagePrompt, isLowerGrade);
        slidesWithImages.push({
            slideTitle: cleanText(struct.slideTitle),
            slideContent: cleanText(struct.slideContent),
            imageData: img || undefined
        });
        await new Promise(r => setTimeout(r, 400));
    }
    return slidesWithImages;
};

export const generateSlides = async (formData: LessonPlanFormState): Promise<Blob> => {
    const contents = await prepareSlideContent(formData);
    return createPptxPresentation(formData.lessonTitle, contents, formData);
};

