                              <p className="text-sm">មិនទាន់មានរូបភាព</p>
                            </div>
                          )}
                        </div>
                        <div className="w-1/2 flex flex-col justify-start">
                          <div className="text-[1.8vw] lg:text-2xl text-slate-600 dark:text-slate-300 leading-relaxed font-medium">
